  --brand-soft:#e4ecfb;
  --on-brand:#ffffff;
  --warn:#b7710a;
  --warn-soft:#fff4de;
  --warn-line:#f3c56f;
  --danger:#b4202a;
  --danger-soft:#fde9ea;
  --ok:#1f7a4d;
  --ok-soft:#e3f4ea;
  --shadow:0 1px 2px rgba(13,44,107,.06),0 8px 24px rgba(13,44,107,.08);
  --display:"Archivo",system-ui,"Segoe UI",sans-serif;
