}
@media (prefers-color-scheme: dark){
  :root:not([data-theme="light"]){
    --bg:#0f1524;--surface:#172035;--surface-2:#1f2a44;--fg:#e8ecf5;--muted:#9aa6c2;--line:#2c3854;
    --brand:#1a3a7c;--brand-2:#6f9cf0;--brand-soft:#1d2d52;--on-brand:#ffffff;
    --warn:#f2c46d;--warn-soft:#3a2d10;--warn-line:#7a5a15;
    --danger:#ff8a93;--danger-soft:#43171b;--ok:#7fd3a3;--ok-soft:#153324;
    --shadow:0 1px 2px rgba(0,0,0,.4),0 8px 24px rgba(0,0,0,.35);color-scheme:dark;
  }
}
:root[data-theme="dark"]{
  --bg:#0f1524;--surface:#172035;--surface-2:#1f2a44;--fg:#e8ecf5;--muted:#9aa6c2;--line:#2c3854;
  --brand:#1a3a7c;--brand-2:#6f9cf0;--brand-soft:#1d2d52;--on-brand:#ffffff;
  --warn:#f2c46d;--warn-soft:#3a2d10;--warn-line:#7a5a15;
  --danger:#ff8a93;--danger-soft:#43171b;--ok:#7fd3a3;--ok-soft:#153324;
  --shadow:0 1px 2px rgba(0,0,0,.4),0 8px 24px rgba(0,0,0,.35);color-scheme:dark;
}
*{box-sizing:border-box}
html,body{height:100%}
body{margin:0;background:var(--bg);color:var(--fg);font-family:var(--body);font-size:17px;line-height:1.55}
button{font:inherit;color:inherit;cursor:pointer}
a{color:var(--brand-2)}
:focus-visible{outline:3px solid var(--brand-2);outline-offset:2px}
@media (prefers-reduced-motion: reduce){*{transition:none!important;animation:none!important}}

/* Top band */
.top{background:var(--brand);color:var(--on-brand)}
.top-in{max-width:1180px;margin:0 auto;padding-block:14px;padding-left:max(16px,env(safe-area-inset-left,0px));padding-right:max(16px,env(safe-area-inset-right,0px));display:flex;align-items:center;gap:16px;flex-wrap:wrap}
.logo{display:flex;align-items:center;gap:10px;font-family:var(--display);font-weight:700;letter-spacing:.08em;font-size:20px}
.logo svg{width:28px;height:28px}
.top .eyebrow{font-size:13px;letter-spacing:.12em;text-transform:uppercase;opacity:.8;font-family:var(--display);font-weight:500}
.top .ttl{font-family:var(--display);font-weight:600;font-size:18px;line-height:1.2}
.top .sep{width:1px;height:34px;background:rgba(255,255,255,.3)}
