.btn-platform{display:inline-flex;align-items:center;gap:8px;background:#fff;color:#0d2c6b;text-decoration:none;border-radius:6px;padding:8px 14px;font-weight:600;font-size:15px;white-space:nowrap}
.btn-platform svg{width:16px;height:16px}
.progress{height:4px;background:rgba(255,255,255,.18)}
.progress i{display:block;height:100%;background:#f5a623;width:0;transition:width .35s ease}

/* Body grid */
.wrap{max-width:1180px;margin:0 auto;padding-block:24px 48px;padding-left:max(16px,env(safe-area-inset-left,0px));padding-right:max(16px,env(safe-area-inset-right,0px));display:grid;grid-template-columns:280px minmax(0,1fr);gap:28px;align-items:start}
@media (max-width:860px){.wrap{grid-template-columns:minmax(0,1fr);gap:16px}}

/* Index */
.index{position:sticky;top:calc(env(safe-area-inset-top,0px) + 16px)}
@media (max-width:860px){.index{position:static}}
.index h2{font-family:var(--display);font-size:12px;letter-spacing:.14em;text-transform:uppercase;color:var(--muted);margin:0 0 10px;font-weight:600}
.sec{margin-bottom:14px}
.sec-h{display:flex;align-items:baseline;gap:8px;flex-wrap:wrap;font-family:var(--display);font-weight:600;font-size:15px;margin:0 0 6px}
.sec-h .k{display:inline-grid;place-items:center;width:22px;height:22px;border-radius:4px;background:var(--brand);color:var(--on-brand);font-size:12px}
.steps{list-style:none;margin:0;padding:0;display:grid;gap:2px}
.steps button{width:100%;text-align:left;border:0;background:transparent;border-radius:6px;padding:7px 10px 7px 8px;display:flex;align-items:center;gap:10px;font-size:15px;line-height:1.3;color:var(--fg)}
.steps button:hover{background:var(--surface-2)}
.steps button[aria-current="step"]{background:var(--brand-soft);color:var(--brand-2);font-weight:600}
.steps .n{font-variant-numeric:tabular-nums;color:var(--muted);width:20px;flex:none;text-align:right;font-size:13px}
.steps button[aria-current="step"] .n{color:var(--brand-2)}
.steps .done{width:16px;height:16px;flex:none;margin-left:auto;color:var(--ok);visibility:hidden}
.steps button.is-done .done{visibility:visible}
.faq-link{margin-top:6px;border-top:1px solid var(--line);padding-top:12px}
.faq-link button{border:1px solid var(--line);background:var(--surface);border-radius:6px;padding:8px 12px;width:100%;text-align:left;display:flex;align-items:center;gap:10px;font-size:15px}
.faq-link button[aria-current="step"]{border-color:var(--brand-2);color:var(--brand-2);font-weight:600}
.faq-link svg{width:18px;height:18px;flex:none}

/* Phone chips: sections as a scroll row, steps as dots */
.chips{display:none}
@media (max-width:860px){
  .index .desk{display:none}
  .chips{display:flex;gap:8px;overflow-x:auto;padding-bottom:6px;scrollbar-width:none}
  .chips::-webkit-scrollbar{display:none}
  .chips button{flex:none;border:1px solid var(--line);background:var(--surface);border-radius:999px;padding:7px 12px;font-size:14px;display:flex;align-items:center;gap:8px}
  .chips button[aria-current="step"]{background:var(--brand);color:var(--on-brand);border-color:var(--brand)}
  .chips .k{font-family:var(--display);font-weight:700}
}

/* Step card */
.card{background:var(--surface);border:1px solid var(--line);border-radius:12px;box-shadow:var(--shadow);overflow:hidden;min-width:0}
.card-h{padding:22px 28px 0;display:grid;gap:6px}
@media (max-width:600px){.card-h{padding:18px 18px 0}}
.eyebrow{font-family:var(--display);font-size:12px;letter-spacing:.14em;text-transform:uppercase;color:var(--muted);font-weight:600;display:flex;gap:10px;align-items:center;flex-wrap:wrap}
.eyebrow .pill{background:var(--brand-soft);color:var(--brand-2);border-radius:999px;padding:2px 10px;letter-spacing:.06em}
h1.step-t{font-family:var(--display);font-weight:700;font-size:clamp(24px,3vw,32px);line-height:1.15;margin:0;text-wrap:balance;display:flex;gap:14px;align-items:flex-start}
h1.step-t .big{font-variant-numeric:tabular-nums;color:var(--brand-2);flex:none;min-width:1.4em}
.card-b{padding:18px 28px 28px;display:grid;gap:20px}
@media (max-width:600px){.card-b{padding:14px 18px 20px}}
.lead{font-size:18px;margin:0;max-width:62ch}
.lead strong,.lead b{font-weight:600}
.ui{display:inline-block;border:1px solid var(--line);background:var(--surface-2);border-radius:4px;padding:0 6px;font-size:.92em;font-weight:600;white-space:nowrap}
.cases{margin:0;padding:0;list-style:none;display:grid;gap:10px;max-width:62ch}
.cases li{display:grid;grid-template-columns:auto minmax(0,1fr);gap:12px;align-items:start;background:var(--surface-2);border-radius:8px;padding:12px 14px}
.cases .who{font-family:var(--display);font-weight:600;font-size:13px;letter-spacing:.04em;text-transform:uppercase;color:var(--brand-2);padding-top:3px;white-space:nowrap}

/* Figures */
.figs{display:grid;gap:16px;grid-template-columns:repeat(auto-fit,minmax(min(100%,280px),1fr))}
figure{margin:0;min-width:0;display:grid;gap:8px;align-content:start}
figure button{border:1px solid var(--line);background:var(--surface-2);border-radius:8px;padding:0;overflow:hidden;display:block;width:100%;position:relative}
figure button img{display:block;width:100%;height:auto;max-height:420px;object-fit:contain;background:#fff}
figure button .zoom{position:absolute;right:8px;bottom:8px;background:rgba(13,44,107,.85);color:#fff;border-radius:6px;padding:4px 8px;font-size:12px;display:flex;align-items:center;gap:6px;font-weight:600}
figure button .zoom svg{width:13px;height:13px}
figcaption{font-size:14px;color:var(--muted)}
figcaption b{color:var(--fg);font-weight:600}
figure.tall button img{max-height:360px}

/* Callouts */
.note{border:1px solid var(--warn-line);background:var(--warn-soft);border-radius:8px;padding:14px 16px;display:grid;grid-template-columns:auto minmax(0,1fr);gap:12px;max-width:72ch}
.note svg{width:22px;height:22px;color:var(--warn);flex:none;margin-top:2px}
.note .nt{font-family:var(--display);font-weight:700;font-size:13px;letter-spacing:.1em;text-transform:uppercase;color:var(--warn);margin:0 0 4px}
.note p{margin:0}
.note.danger{border-color:color-mix(in srgb,var(--danger) 45%,transparent);background:var(--danger-soft)}
.note.danger svg,.note.danger .nt{color:var(--danger)}

/* Actions */
.actions{display:flex;gap:10px;flex-wrap:wrap;align-items:center;border-top:1px solid var(--line);padding-top:18px}
.btn{border:1px solid var(--line);background:var(--surface);border-radius:8px;padding:10px 16px;font-weight:600;font-size:15px;display:inline-flex;align-items:center;gap:8px;text-decoration:none;color:var(--fg)}
.btn svg{width:16px;height:16px}
.btn.primary{background:var(--brand-2);border-color:var(--brand-2);color:#fff}
.btn.ghost{border-color:transparent;color:var(--brand-2)}
.btn:disabled{opacity:.45;cursor:default}
.actions .fill{flex:1}
.btn.done-toggle[aria-pressed="true"]{background:var(--ok-soft);border-color:var(--ok);color:var(--ok)}

/* FAQ view */
.faq{display:grid;gap:12px}
.faq details{border:1px solid var(--line);border-radius:8px;background:var(--surface-2)}
.faq summary{cursor:pointer;padding:12px 16px;font-weight:600;font-size:16px;display:flex;gap:10px;align-items:center;list-style:none}
.faq summary::-webkit-details-marker{display:none}
.faq summary .tag{font-family:var(--display);font-size:11px;letter-spacing:.1em;text-transform:uppercase;border-radius:4px;padding:2px 7px;background:var(--brand-soft);color:var(--brand-2);flex:none}
.faq summary .tag.warn{background:var(--warn-soft);color:var(--warn)}
.faq summary .tag.danger{background:var(--danger-soft);color:var(--danger)}
.faq .ans{padding:0 16px 14px;max-width:70ch}
.faq .ans p{margin:0 0 8px}
.faq .ans a.jump{font-weight:600}
.search{width:100%;border:1px solid var(--line);background:var(--surface);color:var(--fg);border-radius:8px;padding:10px 14px;font-size:16px}

/* Lightbox */
.lb{position:fixed;inset:0;background:rgba(5,10,25,.88);display:grid;place-items:center;padding:calc(env(safe-area-inset-top,0px) + 16px) max(16px,env(safe-area-inset-right,0px)) calc(env(safe-area-inset-bottom,0px) + 16px) max(16px,env(safe-area-inset-left,0px));z-index:50}
.lb img{max-width:100%;max-height:85vh;border-radius:6px;background:#fff}
.lb figcaption{color:#e8ecf5;text-align:center;margin-top:10px;font-size:15px}
.lb .x{position:absolute;top:calc(env(safe-area-inset-top,0px) + 12px);right:calc(env(safe-area-inset-right,0px) + 12px);background:#fff;color:#0d2c6b;border:0;border-radius:999px;width:38px;height:38px;font-size:20px;font-weight:700}

.foot{max-width:1180px;margin:0 auto;padding-block:0 32px;padding-left:max(16px,env(safe-area-inset-left,0px));padding-right:max(16px,env(safe-area-inset-right,0px));font-size:14px;color:var(--muted)}
.foot a{color:var(--muted)}
</style>

