  figs:[{i:"image13", n:13, c:"Inicio de sesión.", tall:true}],
  link:true},
 {n:11, s:"D", t:"Verificación en dos pasos",
  p:`Recibirás en tu correo un código de verificación de <b>6 dígitos</b>. Captúralo en la pantalla <b>“Verificación en dos pasos”</b> y da clic en <span class="ui">Verificar</span> para acceder a la plataforma.`,
  figs:[{i:"image14", n:14, c:"Verificación en dos pasos.", tall:true},{i:"image15", n:15, c:"Correo con el código de verificación."}],
  note:{t:"Importante", h:`El código de verificación expira en <b>10 minutos</b>. Si no lo recibes, da clic en <b>“Reenviar código”</b>. Si no solicitaste el inicio de sesión, cambia tu contraseña de inmediato.`}},
];

const FAQ = [
 {tag:"Cuenta", q:"No recibí el correo de invitación", a:`Revisa la carpeta de correo no deseado buscando el remitente “Notificaciones Automáticas” y el asunto “You have been invited to VIGIA”. Si no está, solicita una nueva invitación al administrador de la plataforma.`, go:1},
 {tag:"Cuenta", cls:"warn", q:"Mi invitación ya venció", a:`La invitación vence a las 24 horas de recibida. Si no activaste tu cuenta dentro de ese plazo, solicita una nueva invitación al administrador de la plataforma.`, go:1},
 {tag:"Cuenta", cls:"warn", q:"Aparece el mensaje “NOT FOUND” al activar la cuenta", a:`Vuelve a cargar la página. Si el mensaje persiste, verifica que estés usando el enlace más reciente que te enviaron.`, go:1},
 {tag:"Acceso", cls:"warn", q:"No me llega el código de verificación", a:`El código expira en 10 minutos. Da clic en “Reenviar código” en la pantalla de verificación y revisa también tu carpeta de correo no deseado.`, go:11},
 {tag:"Acceso", cls:"danger", q:"Recibí un código de verificación sin haber iniciado sesión", a:`Si no solicitaste el inicio de sesión, cambia tu contraseña de inmediato e informa al administrador de la plataforma.`, go:11},
 {tag:"Consulta", q:"No veo el procedimiento que busco en el listado", a:`Si perteneces a una unidad de negocio, solo aparecen los procedimientos de tu unidad y de SAVSA. Si eres de servicios centrales, primero selecciona la unidad de negocio. Si no conoces el código, usa la búsqueda por palabra clave.`, go:4},
 {tag:"Consulta", q:"No conozco el código del procedimiento", a:`Escribe una palabra clave en la barra “Buscar documento” y da clic en Buscar; después selecciona el documento en los resultados.`, go:8},
 {tag:"Descarga", q:"¿En qué formato puedo descargar el documento?", a:`Únicamente en PDF, con el ícono de descarga en la parte superior derecha del visor.`, go:7},
 {tag:"Descarga", cls:"danger", q:"¿Puedo guardar o imprimir una copia para consultarla después?", a:`Puedes hacerlo, pero cualquier copia impresa o descargada se considera NO CONTROLADA. Para consultar la versión vigente, ingresa siempre a la plataforma.`, go:7},
];

let cur = 1;            // 1..11 or 'faq'
let done = new Set();
try{ const d = JSON.parse(localStorage.getItem('vigia-guia-done')||'[]'); done = new Set(d); }catch(e){}
function saveDone(){ try{ localStorage.setItem('vigia-guia-done', JSON.stringify([...done])); }catch(e){} }

function esc(s){return s.replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;");}

function buildIndex(){
  const idx = document.getElementById('index');
  idx.innerHTML = SECTIONS.map(sec => `
    <div class="sec">
      <h3 class="sec-h"><span class="k">${sec.k}</span>${sec.t}${sec.sub?`<span style="flex-basis:100%;padding-left:30px;font-weight:400;color:var(--muted);font-size:13px;margin-top:-4px">(${sec.sub})</span>`:""}</h3>
      <ul class="steps">${STEPS.filter(s=>s.s===sec.k).map(s=>`
        <li><button type="button" data-go="${s.n}" class="${done.has(s.n)?'is-done':''}"><span class="n">${s.n}</span>${esc(s.t)}${ICON_CHK}</button></li>`).join("")}
      </ul>
    </div>`).join("");
  const chips = document.getElementById('chips');
  chips.innerHTML = SECTIONS.map(sec=>`<button type="button" data-gosec="${sec.k}"><span class="k">${sec.k}</span>${sec.t}</button>`).join("")
    + `<button type="button" data-go="faq">Problemas frecuentes</button>`;
}

function render(){
  const card = document.getElementById('card');
  document.querySelectorAll('[data-go],[data-gosec]').forEach(b=>b.removeAttribute('aria-current'));
  if(cur==='faq'){
    document.getElementById('bar').style.width='100%';
    document.getElementById('faqBtn').setAttribute('aria-current','step');
    document.querySelector('#chips [data-go="faq"]').setAttribute('aria-current','step');
    card.innerHTML = `
      <div class="card-h">
        <div class="eyebrow"><span class="pill">Apoyo</span> Resuelve dudas sin salir de la guía</div>
        <h1 class="step-t">Problemas frecuentes</h1>
      </div>
      <div class="card-b">
        <input class="search" id="faqSearch" type="search" placeholder="Filtra por palabra: código, invitación, PDF…" aria-label="Filtrar preguntas">
        <div class="faq" id="faqList">${FAQ.map((f,i)=>`
          <details data-text="${esc((f.q+' '+f.a).toLowerCase())}">
            <summary><span class="tag ${f.cls||''}">${f.tag}</span>${esc(f.q)}</summary>
            <div class="ans"><p>${esc(f.a)}</p><a class="jump" href="#paso-${f.go}">Ver el paso ${f.go} →</a></div>
          </details>`).join("")}
        </div>
        <div class="actions">
          <button class="btn" type="button" data-go="11">← Paso 11</button>
          <span class="fill"></span>
          <button class="btn primary" type="button" data-go="1">Volver al inicio</button>
        </div>
      </div>`;
    const inp = card.querySelector('#faqSearch');
    inp.addEventListener('input',()=>{
      const q = inp.value.trim().toLowerCase();
      card.querySelectorAll('#faqList details').forEach(d=>{ d.hidden = q && !d.dataset.text.includes(q); });
    });
    card.scrollIntoView({block:'start',behavior:'smooth'});
    return;
  }
  const s = STEPS[cur-1];
  const sec = SECTIONS.find(x=>x.k===s.s);
  document.getElementById('bar').style.width = (cur/STEPS.length*100)+'%';
  document.querySelector(`#index [data-go="${cur}"]`).setAttribute('aria-current','step');
  document.querySelector(`#chips [data-gosec="${s.s}"]`).setAttribute('aria-current','step');
  const inSec = STEPS.filter(x=>x.s===s.s);
  card.innerHTML = `
    <div class="card-h">
      <div class="eyebrow"><span class="pill">${sec.k} · ${esc(sec.t)}</span> Paso ${cur} de ${STEPS.length}</div>
      <h1 class="step-t"><span class="big">${cur}.</span><span>${esc(s.t)}</span></h1>
    </div>
    <div class="card-b">
      <p class="lead">${s.p}</p>
      ${s.cases?`<ul class="cases">${s.cases.map(c=>`<li><span class="who">${esc(c.w)}</span><span>${esc(c.d)}</span></li>`).join("")}</ul>`:""}
      <div class="figs">${s.figs.map(f=>`
        <figure class="${f.tall?'tall':''}">
          <button type="button" data-zoom="${f.i}" aria-label="Ampliar figura ${f.n}">
            <img src="${IMG[f.i]}" alt="Figura ${f.n}: ${esc(f.c)}" loading="lazy">
            <span class="zoom"><svg viewBox="0 0 16 16" aria-hidden="true"><circle cx="7" cy="7" r="4.5" fill="none" stroke="currentColor" stroke-width="1.7"/><path d="m10.5 10.5 3.5 3.5M7 5v4M5 7h4" stroke="currentColor" stroke-width="1.7" stroke-linecap="round"/></svg>Ampliar</span>
          </button>
          <figcaption><b>Figura ${f.n}.</b> ${esc(f.c)}</figcaption>
        </figure>`).join("")}
      </div>
      ${s.note?`<div class="note ${s.note.danger?'danger':''}" role="note">${ICON_WARN}<div><p class="nt">${s.note.t}</p><p>${s.note.h}</p></div></div>`:""}
      <div class="actions">
        <button class="btn" type="button" data-go="${cur-1}" ${cur===1?'disabled':''}>← Anterior</button>
        ${s.link?`<a class="btn ghost" href="${PLAT}" target="_blank" rel="noopener">${ICON_EXT} Abrir la plataforma</a>`:""}
        <span class="fill"></span>
        <button class="btn done-toggle" type="button" id="doneBtn" aria-pressed="${done.has(cur)}">${done.has(cur)?'✓ Completado':'Marcar como hecho'}</button>
        ${cur<STEPS.length?`<button class="btn primary" type="button" data-go="${cur+1}">Siguiente →</button>`:`<button class="btn primary" type="button" data-go="faq">Problemas frecuentes →</button>`}
      </div>
    </div>`;
  card.querySelector('#doneBtn').addEventListener('click',e=>{
    if(done.has(cur)) done.delete(cur); else done.add(cur);
    saveDone();
    const b = document.querySelector(`#index [data-go="${cur}"]`);
    b.classList.toggle('is-done', done.has(cur));
    e.currentTarget.setAttribute('aria-pressed', done.has(cur));
    e.currentTarget.textContent = done.has(cur)?'✓ Completado':'Marcar como hecho';
  });
  if(window.innerWidth<=860) card.scrollIntoView({block:'start',behavior:'smooth'});
}

function go(n){
  if(n==='faq'){ cur='faq'; }
  else { n=+n; if(n<1||n>STEPS.length) return; cur=n; }
  try{ history.replaceState(null,'', cur==='faq'?'#faq':`#paso-${cur}`); }catch(e){}
  render();
}

document.addEventListener('click', e=>{
  const g = e.target.closest('[data-go]');
  if(g){ go(g.dataset.go); return; }
  const gs = e.target.closest('[data-gosec]');
  if(gs){ go(STEPS.find(s=>s.s===gs.dataset.gosec).n); return; }
  const j = e.target.closest('a.jump');
  if(j){ e.preventDefault(); const m=j.getAttribute('href').match(/paso-(\d+)/); if(m) go(m[1]); return; }
  const z = e.target.closest('[data-zoom]');
  if(z){ openLB(z.dataset.zoom, z.nextElementSibling.textContent); return; }
});
document.addEventListener('keydown', e=>{
  if(document.querySelector('.lb')){ if(e.key==='Escape') closeLB(); return; }
  if(e.target.matches('input,textarea')) return;
  if(e.key==='ArrowRight' && cur!=='faq' && cur<STEPS.length) go(cur+1);
  if(e.key==='ArrowLeft' && cur!=='faq' && cur>1) go(cur-1);
});
function openLB(key, cap){
  const d = document.createElement('div'); d.className='lb'; d.setAttribute('role','dialog'); d.setAttribute('aria-label','Figura ampliada');
  d.innerHTML = `<button class="x" type="button" aria-label="Cerrar">×</button><figure style="margin:0;max-width:1100px"><img src="${IMG[key]}" alt=""><figcaption>${esc(cap)}</figcaption></figure>`;
  d.addEventListener('click', e=>{ if(e.target===d || e.target.closest('.x')) closeLB(); });
  document.body.appendChild(d); d.querySelector('.x').focus();
}
function closeLB(){ const d=document.querySelector('.lb'); if(d) d.remove(); }

buildIndex();
(function start(){
  const h = location.hash||'';
  if(h==='#faq') cur='faq';
  else { const m=h.match(/^#paso-(\d+)$/); if(m && +m[1]>=1 && +m[1]<=STEPS.length) cur=+m[1]; }
  render();
})();
</script>

</body></html>